pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title SnapVault - 私密付费内容（阅后即焚）的链上付款与访问记录
/// @notice 合约负责定价、收款分账与购买权限。首次打开后的展示倒计时由交付服务负责。
///         内容密文存链下/DeWEB，解密密钥由链下服务监听 Purchase 事件后经 TapeSend 投递（TODO）。
contract SnapVault is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Content {
        address creator;
        address token;      // address(0) = 原生币 OKB
        uint256 price;
        uint64 viewSeconds; // 首次打开后的展示时长，由客户端/交付服务执行
        uint32 maxSupply;   // 0 = 不限量
        uint32 sold;
        bool active;
        bytes32 blobHash;   // 密文哈希（sha256）
        string blobURI;     // 密文位置 ipfs:// / tape:// / https://
    }

    uint16 public constant MAX_FEE_BPS = 1500;
    uint64 public constant PURCHASE_ACCESS_SECONDS = 24 hours;
    uint16 public feeBps;
    address public treasury;
    uint256 public nextId = 1;
    mapping(address => bool) public allowedTokens;

    mapping(uint256 => Content) public contents;
    mapping(uint256 => mapping(address => uint64)) public accessUntil;
    mapping(uint256 => bool) public ephemeral; // 展示选项，不保证买家不能保存密钥或明文
    mapping(address => mapping(address => uint256)) public balances; // creator => token => amount

    event Listed(uint256 indexed id, address indexed creator, address token, uint256 price, uint64 viewSeconds, uint32 maxSupply, bytes32 blobHash, string blobURI);
    event TokenAllowed(address indexed token, bool allowed);
    event Delisted(uint256 indexed id);
    event Purchase(uint256 indexed id, address indexed fan, address indexed creator, address token, uint256 price, uint256 fee, uint64 accessUntil);
    event Withdraw(address indexed creator, address indexed token, uint256 amount);
    event FeeUpdated(uint16 feeBps, address treasury);
    event DisplayRule(uint256 indexed id, bool ephemeral, uint64 viewSeconds);

    error BadParams();
    error NotCreator();
    error Inactive();
    error SoldOut();
    error WrongValue();
    error NothingToWithdraw();
    error AlreadyPurchased();
    error CreatorCannotPurchase();

    constructor(address _treasury, uint16 _feeBps) Ownable(msg.sender) {
        if (_treasury == address(0) || _feeBps > MAX_FEE_BPS) revert BadParams();
        treasury = _treasury;
        feeBps = _feeBps;
    }

    function setFee(uint16 _feeBps, address _treasury) external onlyOwner {
        if (_treasury == address(0) || _feeBps > MAX_FEE_BPS) revert BadParams();
        feeBps = _feeBps;
        treasury = _treasury;
        emit FeeUpdated(_feeBps, _treasury);
    }

    function setTokenAllowed(address token, bool allowed) external onlyOwner {
        if (token == address(0) || token.code.length == 0) revert BadParams();
        allowedTokens[token] = allowed;
        emit TokenAllowed(token, allowed);
    }

    function _checkToken(address token) internal view {
        if (token != address(0) && !allowedTokens[token]) revert BadParams();
    }

    function list(address token, uint256 price, uint64 viewSeconds, uint32 maxSupply, bytes32 blobHash, string calldata blobURI)
        external returns (uint256 id)
    {
        return _list(token, price, viewSeconds, maxSupply, blobHash, blobURI, true);
    }

    function listWithOptions(address token, uint256 price, uint64 viewSeconds, uint32 maxSupply, bytes32 blobHash, string calldata blobURI, bool burn)
        external returns (uint256 id)
    {
        return _list(token, price, viewSeconds, maxSupply, blobHash, blobURI, burn);
    }

    function _list(address token, uint256 price, uint64 viewSeconds, uint32 maxSupply, bytes32 blobHash, string memory blobURI, bool burn)
        internal returns (uint256 id)
    {
        _checkToken(token);
        if (price == 0 || viewSeconds == 0 || blobHash == bytes32(0)) revert BadParams();
        id = nextId++;
        contents[id] = Content(msg.sender, token, price, viewSeconds, maxSupply, 0, true, blobHash, blobURI);
        ephemeral[id] = burn;
        emit Listed(id, msg.sender, token, price, viewSeconds, maxSupply, blobHash, blobURI);
        emit DisplayRule(id, burn, viewSeconds);
    }

    function delist(uint256 id) external {
        if (contents[id].creator != msg.sender) revert NotCreator();
        contents[id].active = false;
        emit Delisted(id);
    }

    function purchase(uint256 id) external payable virtual nonReentrant {
        _purchase(id);
    }

    function _purchase(uint256 id) internal virtual {
        Content storage c = contents[id];
        if (accessUntil[id][msg.sender] != 0) revert AlreadyPurchased();
        if (!c.active) revert Inactive();
        if (msg.sender == c.creator) revert CreatorCannotPurchase();
        if (c.maxSupply != 0 && c.sold >= c.maxSupply) revert SoldOut();
        _checkToken(c.token);
        uint256 price = c.price;
        if (c.token == address(0)) {
            if (msg.value != price) revert WrongValue();
        } else {
            if (msg.value != 0) revert WrongValue();
            uint256 beforeBalance = IERC20(c.token).balanceOf(address(this));
            IERC20(c.token).safeTransferFrom(msg.sender, address(this), price);
            if (IERC20(c.token).balanceOf(address(this)) != beforeBalance + price) revert WrongValue();
        }
        uint256 fee = (price * feeBps) / 10_000;
        c.sold += 1;
        balances[c.creator][c.token] += price - fee;
        balances[treasury][c.token] += fee;
        // 购买资格与首次打开后的 5/10/30 秒展示是两件事。
        uint64 until = uint64(block.timestamp) + PURCHASE_ACCESS_SECONDS;
        accessUntil[id][msg.sender] = until;
        emit Purchase(id, msg.sender, c.creator, c.token, price, fee, until);
    }

    function hasAccess(uint256 id, address fan) external view returns (bool) {
        return accessUntil[id][fan] != 0 && accessUntil[id][fan] >= block.timestamp;
    }

    function withdraw(address token) external nonReentrant {
        uint256 amt = balances[msg.sender][token];
        if (amt == 0) revert NothingToWithdraw();
        balances[msg.sender][token] = 0;
        if (token == address(0)) {
            (bool ok, ) = msg.sender.call{value: amt}("");
            require(ok, "transfer failed");
        } else {
            IERC20(token).safeTransfer(msg.sender, amt);
        }
        emit Withdraw(msg.sender, token, amt);
    }
}
"},"contracts/SnapVaultCheckout.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import {SnapVault} from "./SnapVault.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface IDeliveryHub {
    struct Key { address container; bytes32 endpoint; bool opened; address current; uint8 suite; uint16 keyIndex; bytes32 key; bool usable; uint32 version; uint64 chains; }
    function keyFor(address circuits, uint256 tokenId) external view returns (Key memory);
}
/// @notice Test checkout. A delivery-service quote is required BEFORE taking money.
/// A quote attests readiness, not guaranteed delivery. No automatic refunds or audit.
contract SnapVaultCheckout is SnapVault {
    address public immutable deliveryHub;
    address public deliveryOperator;
    event OperatorUpdated(address indexed previousOperator, address indexed newOperator);
    bytes32 public constant QUOTE_TYPEHASH = keccak256("DeliveryQuote(uint256 id,address buyer,address circuits,uint256 tokenId,bytes32 key,uint256 deadline)");
    mapping(uint256 => mapping(address => bytes32)) public recipient;
    event DeliveryRequested(uint256 indexed id, address indexed buyer, address circuits, uint256 tokenId, bytes32 endpoint, bytes32 key);
    error DeliveryNotReady();
    constructor(address treasury_, uint16 fee_, address hub_, address operator_)
        SnapVault(treasury_, fee_) {
        if (hub_ == address(0) || operator_ == address(0)) revert BadParams();
        deliveryHub = hub_; deliveryOperator = operator_;
    }
    function setOperator(address newOperator) external onlyOwner {
        if (newOperator == address(0)) revert BadParams();
        emit OperatorUpdated(deliveryOperator, newOperator);
        deliveryOperator = newOperator;
    }

    // Legacy checkout cannot bypass delivery authorization.
    function purchase(uint256) external payable override { revert DeliveryNotReady(); }
    function quoteDigest(uint256 id, address buyer, address circuits, uint256 tokenId, bytes32 key, uint256 deadline) public view returns (bytes32) {
        bytes32 domain = keccak256(abi.encode(keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"), keccak256("SnapVaultCheckout"), keccak256("1"), block.chainid, address(this)));
        return keccak256(abi.encodePacked(hex"1901", domain, keccak256(abi.encode(QUOTE_TYPEHASH, id, buyer, circuits, tokenId, key, deadline))));
    }
    function purchaseDelivered(uint256 id, address circuits, uint256 tokenId, bytes32 key, uint256 deadline, bytes calldata signature) external payable nonReentrant {
        if (deadline < block.timestamp || deadline > block.timestamp + 5 minutes || deliveryHub.code.length == 0) revert DeliveryNotReady();
        if (ECDSA.recover(quoteDigest(id, msg.sender, circuits, tokenId, key, deadline), signature) != deliveryOperator) revert DeliveryNotReady();
        IDeliveryHub.Key memory target = IDeliveryHub(deliveryHub).keyFor(circuits, tokenId);
        if (!target.opened || !target.usable || target.suite != 1 || target.current != msg.sender || target.key != key || target.chains == 0) revert DeliveryNotReady();
        recipient[id][msg.sender] = target.endpoint;
        _purchase(id);
        emit DeliveryRequested(id, msg.sender, circuits, tokenId, target.endpoint, key);
    }
}
"},"contracts/SnapVaultDirect.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import {SnapVaultCheckout} from "./SnapVaultCheckout.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/// @notice Ordinary wallets need no TapeOut container. Both checkout routes
/// require an operator readiness quote before payment. Delivery remains a service.
contract SnapVaultDirect is SnapVaultCheckout {
    using SafeERC20 for IERC20;
    struct Payment { address token; uint256 amount; bool refunded; }
    mapping(uint256 => mapping(address => Payment)) public payments;
    event DeliveryRefunded(uint256 indexed id, address indexed buyer, address token, uint256 amount);
    bytes32 public constant DIRECT_TYPEHASH = keccak256("DirectQuote(uint256 id,address buyer,bytes32 keyHash,uint256 deadline)");
    mapping(uint256 => mapping(address => bytes32)) public directKeyHash;
    event DirectRequested(uint256 indexed id, address indexed buyer, bytes32 keyHash);
    constructor(address treasury_, uint16 fee_, address hub_, address operator_)
        SnapVaultCheckout(treasury_, fee_, hub_, operator_) {}

    function directDigest(uint256 id, address buyer, bytes32 keyHash, uint256 deadline) public view returns (bytes32) {
        bytes32 domain = keccak256(abi.encode(keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"), keccak256("SnapVaultDirect"), keccak256("1"), block.chainid, address(this)));
        return keccak256(abi.encodePacked(hex"1901", domain, keccak256(abi.encode(DIRECT_TYPEHASH, id, buyer, keyHash, deadline))));
    }
    function purchaseDirect(uint256 id, bytes32 keyHash, uint256 deadline, bytes calldata signature) external payable nonReentrant {
        if (keyHash == bytes32(0) || deadline < block.timestamp || deadline > block.timestamp + 5 minutes) revert DeliveryNotReady();
        if (ECDSA.recover(directDigest(id, msg.sender, keyHash, deadline), signature) != deliveryOperator) revert DeliveryNotReady();
        directKeyHash[id][msg.sender] = keyHash;
        _purchase(id);
        emit DirectRequested(id, msg.sender, keyHash);
    }

    function _purchase(uint256 id) internal override {
        if (payments[id][msg.sender].refunded) revert AlreadyPurchased();
        super._purchase(id);
        Content storage c = contents[id];
        payments[id][msg.sender] = Payment(c.token, c.price, false);
    }

    /// @notice Owner adjudicates an off-chain delivery failure and funds a FULL refund.
    /// Existing creator/treasury credits are not seized, even if already withdrawn.
    /// This is a funded recovery path, not trustless proof of non-delivery.
    function refundDelivery(uint256 id, address buyer) external payable onlyOwner nonReentrant {
        Payment storage p = payments[id][buyer];
        if (p.amount == 0 || p.refunded) revert BadParams();
        p.refunded = true;
        accessUntil[id][buyer] = 0;
        delete directKeyHash[id][buyer];
        delete recipient[id][buyer];
        if (p.token == address(0)) {
            if (msg.value != p.amount) revert WrongValue();
            (bool ok,) = buyer.call{value: p.amount}("");
            require(ok, "refund transfer failed");
        } else {
            if (msg.value != 0) revert WrongValue();
            uint256 beforeBalance = IERC20(p.token).balanceOf(address(this));
            IERC20(p.token).safeTransferFrom(msg.sender, address(this), p.amount);
            if (IERC20(p.token).balanceOf(address(this)) != beforeBalance + p.amount) revert WrongValue();
            IERC20(p.token).safeTransfer(buyer, p.amount);
        }
        emit DeliveryRefunded(id, buyer, p.token, p.amount);
    }
}
